INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3030, 494, 4, NULL, '昆明地铁到龙头街站再打车去植物园，这个路线好，收藏了。', 21, '2026-06-09 13:53:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3031, 494, 9, NULL, '周五回昆明票确实紧张，我们提前五天买才抢到。', 16, '2026-06-16 11:53:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3032, 495, 23, NULL, '四月确实完美，我们也是那个时间去的，人少花多。', 8, '2026-02-11 16:03:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3033, 495, 2, NULL, '暑假去大理差点被挤哭，再也不敢旺季带娃了。', 19, '2026-02-14 15:03:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3034, 495, 43, NULL, '防晒提醒太重要，云南的太阳看着温和其实毒。', 8, '2026-02-06 12:03:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3035, 495, 28, NULL, '三月街我们碰上了，住宿翻倍还订不到。', 11, '2026-02-13 14:03:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3036, 495, 22, NULL, '冬天洱海风真的很大，孩子吹得流鼻涕。', 17, '2026-02-10 10:03:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3037, 495, 3, NULL, '儿童润肤露必备，我们忘带了，孩子脸皴了。', 22, '2026-02-09 23:03:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3038, 495, 18, NULL, '九月去怎么样？稻田黄了应该很美吧。', 21, '2026-02-05 20:03:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3039, 496, 33, NULL, '确实，大理很多民宿没有围栏，上次孩子差点冲进水里，吓死了。', 15, '2026-04-15 03:11:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3040, 496, 20, NULL, '昆明住火车站附近真的方便，我们那次第二天坐动车去大理，走路就到。', 8, '2026-04-15 21:11:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3041, 496, 14, NULL, '石林当天来回就够了，带孩子住一晚反而折腾。', 24, '2026-04-09 17:11:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3042, 496, 12, NULL, '才村那边家庭房很少，我们订的时候费了好大劲。', 4, '2026-04-09 03:11:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3043, 496, 25, NULL, '大理晚上是真冷，没空调的民宿要慎重。', 17, '2026-04-09 07:11:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3044, 497, 41, NULL, '动车票真的得早买，我们临时买站票抱了孩子一路。', 8, '2026-03-30 06:00:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3045, 497, 25, NULL, '石林电瓶车是必花的钱，不然孩子走一半就闹。', 1, '2026-03-23 12:00:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3046, 497, 10, NULL, '大理菜市场的水果又便宜又新鲜，比景区强太多。', 7, '2026-03-29 06:00:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3047, 497, 47, NULL, '住宿真的不能太省，隔音不好孩子睡不好。', 5, '2026-03-31 22:00:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3048, 497, 25, NULL, '喂海鸥那个点好，孩子开心还不花钱。', 18, '2026-03-31 01:00:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3049, 498, 4, NULL, '过桥米线孩子真的爱，仪式感满满。', 14, '2026-06-09 00:26:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3050, 498, 12, NULL, '昆明植物园的迷宫太适合耗电了，孩子玩到不想走。', 10, '2026-06-13 05:26:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3051, 498, 48, NULL, '才村到龙龛那段路绝了，安全又美。', 4, '2026-06-10 21:26:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3052, 498, 44, NULL, '石林放最后一天很合理，不然太累。', 12, '2026-06-07 13:26:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3053, 498, 40, NULL, '这个行程不赶，我们照着走了一遍，孩子没闹。', 4, '2026-06-10 11:26:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3054, 499, 15, NULL, '薄羽绒服真是救命，大理晚上风大得怀疑人生。', 21, '2026-02-26 11:54:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3055, 499, 5, NULL, '动车票必须提前订，我们吃过亏。', 21, '2026-02-21 05:54:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3056, 499, 32, NULL, '石林穿洞洞鞋差点滑倒，后怕。', 22, '2026-02-25 15:54:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3057, 499, 40, NULL, '官方公众号查信息最准，别只看游记。', 14, '2026-02-27 00:54:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3058, 499, 35, NULL, '那些没开发的野景点真别带孩子去。', 19, '2026-02-28 09:54:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3059, 500, 13, NULL, '植物园那个迷宫，孩子转了快一个小时，笑死。', 19, '2026-04-28 05:54:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3060, 500, 8, NULL, '在巷子里看老奶奶编草编，孩子回来还念叨。', 18, '2026-04-21 07:54:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3061, 500, 3, NULL, '生态廊道走路就很好，骑车反而太快了。', 19, '2026-04-27 20:54:00');
INSERT INTO comments (id, post_id, user_id, parent_id, content, like_count, created_at) VALUES (3062, 500, 8, NULL, '过桥米线让孩子自己下料，能吃好久。', 1, '2026-04-20 07:54:00');
